import pty
import os
import termios
import struct
import fcntl

def set_winsize(fd, row, col):
    winsize = struct.pack("HHHH", row, col, 0, 0)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, winsize)

def read(fd):
    return os.read(fd, 1024)

pid, fd = pty.fork()
if pid == 0:
    os.execv('./executable', ['./executable', 'next'])
else:
    set_winsize(fd, 40, 120)
    out = b''
    try:
        while True:
            chunk = os.read(fd, 1024)
            if not chunk:
                break
            out += chunk
    except OSError:
        pass
    with open('pty_out.txt', 'wb') as f:
        f.write(out)
