    lines = content.strip().split('\n')
    obj = {}
    current_list_key = None
    for line in lines:
        if not line:
            continue
        if line.startswith('- '):
            if current_list_key:
                val = line[2:].strip()
                if val.startswith('"') and val.endswith('"'):
                    val = val[1:-1]
                obj[current_list_key].append(val)
        else:
            if ':' in line:
                key, val = line.split(':', 1)
                key = key.strip()
                val = val.strip()
                if val == '[]':
                    obj[key] = []
                    current_list_key = key
                elif not val:
                    obj[key] = []
                    current_list_key = key
                else:
                    if val.startswith('"') and val.endswith('"'):
                        val = val[1:-1]
                    obj[key] = val
                    current_list_key = None
    return obj

def dump_yaml(obj):
    lines = []
    keys_order = ['summary', 'notes', 'tags', 'project', 'priority', 'delegatedto', 'subtasks', 'dependencies', 'created', 'resolved', 'due']
    for k in keys_order:
        if k in obj:
            v = obj[k]
            if isinstance(v, list):
                if not v:
                    lines.append(f"{k}: []")
                else:
                    lines.append(f"{k}:")
                    for item in v:
                        lines.append(f"- {item}")
            else:
                if v == "":
                    lines.append(f'{k}: ""')
                else:
                    lines.append(f"{k}: {v}")
    return '\n'.join(lines) + '\n'

