#!/usr/bin/env python3
import sys
import os
import json
import uuid
import datetime
import subprocess

def get_repo_path():
    return os.path.expanduser('~/.dstask')

def init_repo():
    repo_path = get_repo_path()
    if not os.path.exists(repo_path):
        os.makedirs(repo_path)
        for folder in ['active', 'deferred', 'delegated', 'paused', 'pending', 'recurring', 'resolved', 'template']:
            os.makedirs(os.path.join(repo_path, folder), exist_ok=True)
        subprocess.call(['git', '-C', repo_path, 'init'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        subprocess.call(['git', '-C', repo_path, 'config', 'user.email', 'dstask@example.com'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        subprocess.call(['git', '-C', repo_path, 'config', 'user.name', 'dstask'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

def git_commit(msg):
    repo_path = get_repo_path()
    subprocess.call(['git', '-C', repo_path, 'add', '.'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    subprocess.call(['git', '-C', repo_path, 'commit', '-m', msg], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

def parse_yaml(content):
    lines = content.strip().split('\n')
    obj = {}
    current_list_key = None
    for line in lines:
        line = line.strip('\r')
        if not line: continue
        if line.startswith('- '):
            if current_list_key:
                val = line[2:].strip()
                if val.startswith('"') and val.endswith('"'): val = val[1:-1]
                obj[current_list_key].append(val)
        else:
            if ':' in line:
                key, val = line.split(':', 1)
                key = key.strip()
                val = val.strip()
                if val == '[]':
                    obj[key] = []
                    current_list_key = None
                elif not val:
                    obj[key] = []
                    current_list_key = key
                else:
                    if val.startswith('"') and val.endswith('"'): val = val[1:-1]
                    obj[key] = val
                    current_list_key = None
    return obj

def dump_yaml(obj):
    lines = []
    for k in ['summary', 'notes', 'tags', 'project', 'priority', 'delegatedto', 'subtasks', 'dependencies', 'created', 'resolved', 'due']:
        if k in obj:
            v = obj[k]
            if isinstance(v, list):
                if not v: lines.append(f"{k}: []")
                else:
                    lines.append(f"{k}:")
                    for item in v: lines.append(f"- {item}")
            else:
                if v == "": lines.append(f'{k}: ""')
                else: lines.append(f"{k}: {v}")
    return '\n'.join(lines) + '\n'

def get_all_tasks():
    repo_path = get_repo_path()
    tasks = []
    folders = ['active', 'paused', 'pending', 'resolved']
    for folder in folders:
        d = os.path.join(repo_path, folder)
        if not os.path.exists(d): continue
        for fname in os.listdir(d):
            if fname.endswith('.yml'):
                with open(os.path.join(d, fname)) as f:
                    obj = parse_yaml(f.read())
                    obj['uuid'] = fname[:-4]
                    obj['status'] = folder
                    tasks.append(obj)

    # Assign IDs
    # Sort all non-resolved tasks by created time to assign sequential IDs
    open_tasks = [t for t in tasks if t['status'] != 'resolved']
    open_tasks.sort(key=lambda x: x.get('created', ''))
    for i, t in enumerate(open_tasks):
        t['id'] = i + 1
    for t in tasks:
        if t['status'] == 'resolved':
            t['id'] = 0
    return tasks

def save_task(task, folder):
    repo_path = get_repo_path()
    fname = task['uuid'] + '.yml'
    # remove from other folders
    for f in ['active', 'paused', 'pending', 'resolved']:
        p = os.path.join(repo_path, f, fname)
        if os.path.exists(p): os.remove(p)

    out_p = os.path.join(repo_path, folder, fname)
    with open(out_p, 'w') as f:
        f.write(dump_yaml(task))

def cmd_add(args):
    tags = []
    project = ""
    priority = "P2"
    summary = []
    for arg in args:
        if arg.startswith('+'): tags.append(arg[1:])
        elif arg.startswith('project:'): project = arg[8:]
        elif arg in ['P0', 'P1', 'P2', 'P3']: priority = arg
        else: summary.append(arg)

    now = datetime.datetime.utcnow().isoformat() + "Z"
    task = {
        'uuid': str(uuid.uuid4()),
        'summary': ' '.join(summary),
        'notes': '',
        'tags': tags,
        'project': project,
        'priority': priority,
        'delegatedto': '',
        'subtasks': [],
        'dependencies': [],
        'created': now,
        'resolved': '0001-01-01T00:00:00Z',
        'due': '0001-01-01T00:00:00Z'
    }
    save_task(task, 'pending')

    tasks = get_all_tasks()
    t = next(x for x in tasks if x['uuid'] == task['uuid'])
    new_id = t['id']
    msg = f"Added {new_id}: {task['summary']}"
    git_commit(msg)
    if sys.stdout.isatty():
        print(f"\nAdded {new_id}: {task['summary']}")

def cmd_next():
    tasks = get_all_tasks()
    open_tasks = [t for t in tasks if t['status'] in ['active', 'pending', 'paused']]

    # Sort
    def sort_key(t):
        status_val = 0 if t['status'] == 'active' else (1 if t['status'] == 'pending' else 2)
        prio_val = {'P0':0, 'P1':1, 'P2':2, 'P3':3}.get(t.get('priority', 'P2'), 2)
        return (status_val, prio_val, t.get('created', ''))

    open_tasks.sort(key=sort_key)

    if not sys.stdout.isatty():
        # JSON output
        out = []
        for t in open_tasks:
            out.append({
                "uuid": t['uuid'],
                "status": t['status'],
                "id": t['id'],
                "summary": t['summary'],
                "notes": t['notes'],
                "tags": t['tags'],
                "project": t['project'],
                "priority": t['priority'],
                "created": t['created'],
                "resolved": t['resolved'],
                "due": t['due']
            })
        print(json.dumps(out, indent=2))
    else:
        if not open_tasks:
            print("No tasks found. Run `dstask help` for instructions.")
            return

        print("ID  Priority  Tags      Due  Project  Summary")
        for t in open_tasks:
            tags = " ".join(t['tags'])
            print(f"{t['id']:<3} {t['priority']:<9} {tags:<9}      {t['project']:<8} {t['summary']}")
        print(f"\n{len(open_tasks)} tasks.")

def main():
    init_repo()
    args = sys.argv[1:]
    if not args:
        cmd_next()
        return

    cmd = args[0]
    if cmd == 'add':
        cmd_add(args[1:])
    elif cmd == 'next':
        cmd_next()
    # we will add more cmds next

if __name__ == '__main__':
    main()
