    if not os.path.exists(repo_path):
        os.makedirs(repo_path)
        for folder in ['active', 'deferred', 'delegated', 'paused', 'pending', 'recurring', 'resolved', 'template']:
            os.makedirs(os.path.join(repo_path, folder), exist_ok=True)
