        subprocess.call(['git', '-C', repo_path, 'config', 'user.email', 'dstask@example.com'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        subprocess.call(['git', '-C', repo_path, 'config', 'user.name', 'dstask'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

    ids_dir = os.path.join(repo_path, '.git', 'dstask')
    if not os.path.exists(ids_dir):
        os.makedirs(ids_dir, exist_ok=True)

def git_commit(msg):
    repo_path = get_repo_path()
    subprocess.call(['git', '-C', repo_path, 'add', '.'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    subprocess.call(['git', '-C', repo_path, 'commit', '-m', msg], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

def get_ids_map():
    map_file = os.path.join(get_repo_path(), '.git', 'dstask', 'ids.json')
    if os.path.exists(map_file):
        with open(map_file, 'r') as f:
            return json.load(f)
    return {}

def save_ids_map(m):
    map_file = os.path.join(get_repo_path(), '.git', 'dstask', 'ids.json')
    with open(map_file, 'w') as f:
        json.dump(m, f)

def get_next_id():
    m = get_ids_map()
    if not m: return 1
    return max(m.values()) + 1

def assign_id(task_uuid):
    m = get_ids_map()
    if task_uuid in m:
        return m[task_uuid]
    new_id = get_next_id()
    m[task_uuid] = new_id
    save_ids_map(m)
    return new_id

def parse_yaml(content):
    lines = content.strip().split('\n')
    obj = {}
    current_list_key = None
    for line in lines:
        line = line.strip('\r')
        if not line: continue
        if line.startswith('- '):
            if current_list_key:
                val = line[2:].strip()
                if val.startswith('"') and val.endswith('"'): val = val[1:-1]
                obj[current_list_key].append(val)
        else:
            if ':' in line:
                key, val = line.split(':', 1)
                key = key.strip()
                val = val.strip()
                if val == '[]':
                    obj[key] = []
                    current_list_key = None
                elif not val:
                    obj[key] = []
                    current_list_key = key
                else:
                    if val.startswith('"') and val.endswith('"'): val = val[1:-1]
                    obj[key] = val
                    current_list_key = None
    return obj

def dump_yaml(obj):
    lines = []
    for k in ['summary', 'notes', 'tags', 'project', 'priority', 'delegatedto', 'subtasks', 'dependencies', 'created', 'resolved', 'due']:
        if k in obj:
            v = obj[k]
            if isinstance(v, list):
                if not v: lines.append(f"{k}: []")
                else:
                    lines.append(f"{k}:")
                    for item in v: lines.append(f"- {item}")
