                if val.startswith('"') and val.endswith('"'): val = val[1:-1]
                obj[current_list_key].append(val)
        else:
            if ':' in line:
                key, val = line.split(':', 1)
                key = key.strip()
                val = val.strip()
                if val == '[]':
                    obj[key] = []
                    current_list_key = None
                elif not val:
                    obj[key] = []
                    current_list_key = key
